1	// Package ir implements IR generation from optimized AST
2	package ir
3	
4	import (
5		"fmt"
6	
7		"github.com/user/freelang-evolving-compiler/internal/ast"
8	)
9	
10	// Generator converts AST to intermediate representation
11	type Generator struct {
12		tempCount    int
13		labelCount   int
14		currentFn    *Function
15		program      *Program
16		structFields map[string][]string
17	}
18	
19	// NewGenerator creates a new IR generator
20	func NewGenerator() *Generator {
21		return &Generator{
22			tempCount:  0,
23			labelCount: 0,
24			program: &Program{
25				Functions: []Function{},
26				Main:      []Instruction{},
27			},
28			structFields: make(map[string][]string),
29		}
30	}
31	
32	// Generate converts an AST to an IR program
33	func (g *Generator) Generate(root *ast.Node) (*Program, error) {
34		if root == nil {
35			return g.program, nil
36		}
37	
38		// Process program statements
39		if root.Kind == ast.NodeProgram {
40			for _, child := range root.Children {
41				if child.Kind == ast.NodeFnDecl {
42					if err := g.genFnDecl(child); err != nil {
43						return nil, err
44					}
45				} else if child.Kind == ast.NodeStructDecl {
46					if err := g.genStructDecl(child); err != nil {
47						return nil, err
48					}
49				} else {
50					if err := g.genStmt(child); err != nil {
51						return nil, err
52					}
53				}
54			}
55		} else {
56			if err := g.genStmt(root); err != nil {
57				return nil, err
58			}
59		}
60	
61		return g.program, nil
62	}
63	
64	// genFnDecl generates IR for a function declaration
65	func (g *Generator) genFnDecl(node *ast.Node) error {
66		if len(node.Children) < 2 {
67			return fmt.Errorf("function declaration must have name and body")
68		}
69	
70		fnName := node.Children[0].Value
71		body := node.Children[len(node.Children)-1]
72	
73		fn := Function{
74			Name:   fnName,
75			Params: []string{},
76			Body:   []Instruction{},
77		}
78	
79		// Extract parameter names if they exist
80		if len(node.Children) > 2 {
81			for i := 1; i < len(node.Children)-1; i++ {
82				if node.Children[i].Kind == ast.NodeIdent {
83					fn.Params = append(fn.Params, node.Children[i].Value)
84				}
85			}
86		}
87	
88		// Save current function and switch context
89		prevFn := g.currentFn
90		g.currentFn = &fn
91	
92		// Generate OpEnter
93		g.emit(Instruction{Op: OpEnter, Fn: fnName})
94	
95		// Generate body
96		if body.Kind == ast.NodeBlockStmt {
97			for _, stmt := range body.Children {
98				if err := g.genStmt(stmt); err != nil {
99					return err
100				}
101			}
102		} else {
103			if err := g.genStmt(body); err != nil {
104				return err
105			}
106		}
107	
108		// Generate OpLeave if not already there
109		g.emit(Instruction{Op: OpLeave, Fn: fnName})
110	
111		// Add function to program
112		g.program.Functions = append(g.program.Functions, fn)
113		g.currentFn = prevFn
114	
115		return nil
116	}
117	
118	// genStmt generates IR for a statement
119	func (g *Generator) genStmt(node *ast.Node) error {
120		if node == nil {
121			return nil
122		}
123	
124		switch node.Kind {
125		case ast.NodeLetDecl:
126			return g.genLetDecl(node)
127		case ast.NodeIfStmt:
128			return g.genIfStmt(node)
129		case ast.NodeForStmt:
130			return g.genForStmt(node)
131		case ast.NodeReturn:
132			return g.genReturn(node)
133		case ast.NodeStructDecl:
134			return g.genStructDecl(node)
135		case ast.NodeBlockStmt:
136			for _, child := range node.Children {
137				if err := g.genStmt(child); err != nil {
138					return err
139				}
140			}
141			return nil
142		default:
143			// Expression statement
144			_, err := g.genExpr(node)
145			return err
146		}
147	}
148	
149	// genLetDecl generates IR for a let declaration
150	func (g *Generator) genLetDecl(node *ast.Node) error {
151		if len(node.Children) < 2 {
152			return fmt.Errorf("let declaration must have name and value")
153		}
154	
155		varName := node.Children[0].Value
156		valueExpr := node.Children[1]
157	
158		// Generate code for the expression
159		operand, err := g.genExpr(valueExpr)
160		if err != nil {
161			return err
162		}
163	
164		// Copy result to variable
165		g.emit(Instruction{
166			Op:   OpCopy,
167			Dest: Operand{Name: varName},
168			Src1: operand,
169		})
170	
171		return nil
172	}
173	
174	// genIfStmt generates IR for an if statement
175	func (g *Generator) genIfStmt(node *ast.Node) error {
176		if len(node.Children) < 2 {
177			return fmt.Errorf("if statement must have condition and body")
178		}
179	
180		condExpr := node.Children[0]
181		bodyStmt := node.Children[1]
182	
183		// Generate condition
184		condOp, err := g.genExpr(condExpr)
185		if err != nil {
186			return err
187		}
188	
189		// Create end label
190		endLabel := g.newLabel("end")
191	
192		// Jump if false
193		g.emit(Instruction{
194			Op:    OpJumpIfFalse,
195			Src1:  condOp,
196			Label: endLabel,
197		})
198	
199		// Generate body
200		if err := g.genStmt(bodyStmt); err != nil {
201			return err
202		}
203	
204		// Emit end label
205		g.emit(Instruction{
206			Op:    OpLabel,
207			Label: endLabel,
208		})
209	
210		return nil
211	}
212	
213	// genForStmt generates IR for a for statement
214	func (g *Generator) genForStmt(node *ast.Node) error {
215		if len(node.Children) < 3 {
216			return fmt.Errorf("for statement must have iterator, range, and body")
217		}
218	
219		iterName := node.Children[0].Value
220		rangeExpr := node.Children[1]
221		bodyStmt := node.Children[2]
222	
223		// Extract range start and end
224		if rangeExpr.Kind != ast.NodeBinaryExpr || rangeExpr.Value != ".." {
225			return fmt.Errorf("for loop requires range expression (..)")
226		}
227	
228		if len(rangeExpr.Children) < 2 {
229			return fmt.Errorf("range expression requires start and end")
230		}
231	
232		startOp, err := g.genExpr(rangeExpr.Children[0])
233		if err != nil {
234			return err
235		}
236	
237		endOp, err := g.genExpr(rangeExpr.Children[1])
238		if err != nil {
239			return err
240		}
241	
242		// Initialize iterator
243		g.emit(Instruction{
244			Op:   OpCopy,
245			Dest: Operand{Name: iterName},
246			Src1: startOp,
247		})
248	
249		// Create loop and end labels
250		loopLabel := g.newLabel("loop")
251		endLabel := g.newLabel("end")
252	
253		// Emit loop label
254		g.emit(Instruction{
255			Op:    OpLabel,
256			Label: loopLabel,
257		})
258	
259		// Check condition: iterator < end
260		cmpTemp := g.newTemp()
261		g.emit(Instruction{
262			Op:   OpLt,
263			Dest: cmpTemp,
264			Src1: Operand{Name: iterName},
265			Src2: endOp,
266		})
267	
268		// Jump if false (exit loop)
269		g.emit(Instruction{
270			Op:    OpJumpIfFalse,
271			Src1:  cmpTemp,
272			Label: endLabel,
273		})
274	
275		// Generate body
276		if err := g.genStmt(bodyStmt); err != nil {
277			return err
278		}
279	
280		// Increment iterator
281		incrTemp := g.newTemp()
282		g.emit(Instruction{
283			Op:   OpAdd,
284			Dest: incrTemp,
285			Src1: Operand{Name: iterName},
286			Src2: Operand{IsImm: true, ImmVal: 1},
287		})
288		g.emit(Instruction{
289			Op:   OpCopy,
290			Dest: Operand{Name: iterName},
291			Src1: incrTemp,
292		})
293	
294		// Jump back to loop
295		g.emit(Instruction{
296			Op:    OpJump,
297			Label: loopLabel,
298		})
299	
300		// Emit end label
301		g.emit(Instruction{
302			Op:    OpLabel,
303			Label: endLabel,
304		})
305	
306		return nil
307	}
308	
309	// genReturn generates IR for a return statement
310	func (g *Generator) genReturn(node *ast.Node) error {
311		if len(node.Children) == 0 {
312			g.emit(Instruction{Op: OpReturn})
313			return nil
314		}
315	
316		returnOp, err := g.genExpr(node.Children[0])
317		if err != nil {
318			return err
319		}
320	
321		g.emit(Instruction{
322			Op:   OpReturn,
323			Src1: returnOp,
324		})
325	
326		return nil
327	}
328	
329	// genExpr generates IR for an expression and returns the operand
330	func (g *Generator) genExpr(node *ast.Node) (Operand, error) {
331		if node == nil {
332			return Operand{}, fmt.Errorf("nil expression")
333		}
334	
335		switch node.Kind {
336		case ast.NodeIntLit:
337			// Parse integer literal
338			var val int64
339			fmt.Sscanf(node.Value, "%d", &val)
340			return Operand{IsImm: true, ImmVal: val}, nil
341	
342		case ast.NodeStringLit:
343			// String literal
344			return Operand{IsStr: true, SVal: node.Value}, nil
345	
346		case ast.NodeBoolLit:
347			// Boolean literal
348			return Operand{IsBool: true, BVal: node.Value == "true"}, nil
349	
350		case ast.NodeIdent:
351			return Operand{Name: node.Value}, nil
352	
353		case ast.NodeBinaryExpr:
354			return g.genBinaryExpr(node)
355	
356		case ast.NodeCallExpr:
357			return g.genCallExpr(node)
358	
359		case ast.NodeFieldAccess:
360			return g.genFieldAccess(node)
361	
362		case ast.NodeArrayLit:
363			return g.genArrayLit(node)
364	
365		case ast.NodeIndexExpr:
366			return g.genIndexExpr(node)
367	
368		default:
369			return Operand{}, fmt.Errorf("unsupported expression kind: %d", node.Kind)
370		}
371	}
372	
373	// genBinaryExpr generates IR for a binary expression
374	func (g *Generator) genBinaryExpr(node *ast.Node) (Operand, error) {
375		if len(node.Children) < 2 {
376			return Operand{}, fmt.Errorf("binary expression requires 2 operands")
377		}
378	
379		left, err := g.genExpr(node.Children[0])
380		if err != nil {
381			return Operand{}, err
382		}
383	
384		right, err := g.genExpr(node.Children[1])
385		if err != nil {
386			return Operand{}, err
387		}
388	
389		result := g.newTemp()
390		op := g.opcodeFromOp(node.Value)
391	
392		g.emit(Instruction{
393			Op:   op,
394			Dest: result,
395			Src1: left,
396			Src2: right,
397		})
398	
399		return result, nil
400	}
401	
402	// genCallExpr generates IR for a function call
403	func (g *Generator) genCallExpr(node *ast.Node) (Operand, error) {
404		if len(node.Children) == 0 {
405			return Operand{}, fmt.Errorf("call expression requires function name")
406		}
407	
408		fnName := node.Children[0].Value
409	
410		// Special handling for syscall
411		if fnName == "syscall" {
412			if len(node.Children) < 2 {
413				return Operand{}, fmt.Errorf("syscall requires at least syscall number")
414			}
415	
416			// syscall number (always first arg after function name)
417			numOp, err := g.genExpr(node.Children[1])
418			if err != nil {
419				return Operand{}, err
420			}
421	
422			// Additional args (starting from index 2)
423			for i := 2; i < len(node.Children); i++ {
424				argOp, err := g.genExpr(node.Children[i])
425				if err != nil {
426					return Operand{}, err
427				}
428				g.emit(Instruction{
429					Op:   OpParam,
430					Src1: argOp,
431				})
432			}
433	
434			// Emit syscall instruction
435			result := g.newTemp()
436			g.emit(Instruction{
437				Op:   OpSyscall,
438				Dest: result,
439				Src1: numOp,
440			})
441	
442			return result, nil
443		}
444	
445		// Emit parameters for regular function calls
446		for i := 1; i < len(node.Children); i++ {
447			argOp, err := g.genExpr(node.Children[i])
448			if err != nil {
449				return Operand{}, err
450			}
451			g.emit(Instruction{
452				Op:   OpParam,
453				Src1: argOp,
454			})
455		}
456	
457		// Emit call
458		result := g.newTemp()
459		g.emit(Instruction{
460			Op:   OpCall,
461			Dest: result,
462			Fn:   fnName,
463		})
464	
465		return result, nil
466	}
467	
468	// Helper functions
469	
470	func (g *Generator) newTemp() Operand {
471		temp := Operand{
472			IsTemp: true,
473			Name:   fmt.Sprintf("t%d", g.tempCount),
474		}
475		g.tempCount++
476		return temp
477	}
478	
479	func (g *Generator) newLabel(prefix string) string {
480		label := fmt.Sprintf("L_%s_%d", prefix, g.labelCount)
481		g.labelCount++
482		return label
483	}
484	
485	func (g *Generator) emit(instr Instruction) {
486		if g.currentFn != nil {
487			g.currentFn.Body = append(g.currentFn.Body, instr)
488		} else {
489			g.program.Main = append(g.program.Main, instr)
490		}
491	}
492	
493	func (g *Generator) opcodeFromOp(op string) Opcode {
494		switch op {
495		case "+":
496			return OpAdd
497		case "-":
498			return OpSub
499		case "*":
500			return OpMul
501		case "/":
502			return OpDiv
503		case "==":
504			return OpEq
505		case "!=":
506			return OpNe
507		case "<":
508			return OpLt
509		case ">":
510			return OpGt
511		case "<=":
512			return OpLe
513		case ">=":
514			return OpGe
515		default:
516			return OpNoop
517		}
518	}
519	
520	// genStructDecl generates IR for a struct declaration
521	func (g *Generator) genStructDecl(node *ast.Node) error {
522		if node.Value == "" {
523			return fmt.Errorf("struct declaration must have a name")
524		}
525	
526		name := node.Value
527		fields := []string{}
528	
529		// Extract field names from children
530		for _, field := range node.Children {
531			if field.Kind == ast.NodeFieldDecl {
532				fields = append(fields, field.Value)
533			}
534		}
535	
536		// Store struct definition
537		g.structFields[name] = fields
538	
539		// Calculate struct size (8 bytes per field)
540		size := len(fields) * 8
541	
542		// Save current function context
543		prevFn := g.currentFn
544		g.currentFn = nil // Emit to Main context
545	
546		// Emit OpStructDef instruction
547		g.emit(Instruction{
548			Op:   OpStructDef,
549			Fn:   name,
550			Src1: Operand{IsImm: true, ImmVal: int64(size)},
551		})
552	
553		// Restore function context
554		g.currentFn = prevFn
555	
556		return nil
557	}
558	
559	// genFieldAccess generates IR for a field access expression (obj.field)
560	func (g *Generator) genFieldAccess(node *ast.Node) (Operand, error) {
561		if len(node.Children) == 0 {
562			return Operand{}, fmt.Errorf("field access requires object expression")
563		}
564	
565		// Generate IR for object expression
566		objOp, err := g.genExpr(node.Children[0])
567		if err != nil {
568			return Operand{}, err
569		}
570	
571		fieldName := node.Value
572	
573		// Search for field offset in known structs
574		var offset int64
575		found := false
576		for _, fields := range g.structFields {
577			for i, f := range fields {
578				if f == fieldName {
579					offset = int64(i * 8)
580					found = true
581					break
582				}
583			}
584			if found {
585				break
586			}
587		}
588		// If not found, use offset 0 as fallback
589	
590		// Emit OpFieldLoad instruction
591		result := g.newTemp()
592		g.emit(Instruction{
593			Op:   OpFieldLoad,
594			Dest: result,
595			Src1: objOp,
596			Src2: Operand{IsImm: true, ImmVal: offset},
597		})
598	
599		return result, nil
600	}
601	
602	// genArrayLit generates IR for array literals: [1, 2, 3]
603	func (g *Generator) genArrayLit(node *ast.Node) (Operand, error) {
604		// Generate IR for each element and emit as parameter
605		for _, elem := range node.Children {
606			op, err := g.genExpr(elem)
607			if err != nil {
608				return Operand{}, err
609			}
610			g.emit(Instruction{
611				Op:   OpParam,
612				Src1: op,
613			})
614		}
615	
616		// Create array with element count
617		result := g.newTemp()
618		g.emit(Instruction{
619			Op:   OpArrayNew,
620			Dest: result,
621			Src1: Operand{IsImm: true, ImmVal: int64(len(node.Children))},
622		})
623	
624		return result, nil
625	}
626	
627	// genIndexExpr generates IR for array indexing: arr[i]
628	func (g *Generator) genIndexExpr(node *ast.Node) (Operand, error) {
629		if len(node.Children) < 2 {
630			return Operand{}, fmt.Errorf("index expression requires array and index")
631		}
632	
633		arrOp, err := g.genExpr(node.Children[0])
634		if err != nil {
635			return Operand{}, err
636		}
637	
638		idxOp, err := g.genExpr(node.Children[1])
639		if err != nil {
640			return Operand{}, err
641		}
642	
643		result := g.newTemp()
644		g.emit(Instruction{
645			Op:   OpArrayLoad,
646			Dest: result,
647			Src1: arrOp,
648			Src2: idxOp,
649		})
650	
651		return result, nil
652	}
