1	// Package parser implements an AST parser for mini FreeLang
2	package parser
3	
4	import (
5		"fmt"
6	
7		"github.com/user/freelang-evolving-compiler/internal/ast"
8		"github.com/user/freelang-evolving-compiler/internal/lexer"
9	)
10	
11	type Parser struct {
12		l         *lexer.Lexer
13		curToken  ast.Token
14		peekToken ast.Token
15	}
16	
17	// New creates a new parser for the input string
18	func New(input string) *Parser {
19		l := lexer.New(input)
20		p := &Parser{l: l}
21		p.nextToken()
22		p.nextToken()
23		return p
24	}
25	
26	func (p *Parser) nextToken() {
27		p.curToken = p.peekToken
28		p.peekToken = p.l.NextToken()
29	}
30	
31	// ParseProgram parses a complete program
32	func (p *Parser) ParseProgram() (*ast.Node, error) {
33		prog := &ast.Node{
34			Kind:     ast.NodeProgram,
35			Children: []*ast.Node{},
36		}
37	
38		for p.curToken.Type != ast.TokenEOF {
39			stmt, err := p.parseStatement()
40			if err != nil {
41				return nil, err
42			}
43			if stmt != nil {
44				prog.Children = append(prog.Children, stmt)
45			}
46			p.skipSemicolons()
47		}
48	
49		return prog, nil
50	}
51	
52	func (p *Parser) parseStatement() (*ast.Node, error) {
53		switch p.curToken.Type {
54		case ast.TokenLet:
55			return p.parseLetDecl()
56		case ast.TokenFn:
57			return p.parseFnDecl()
58		case ast.TokenIf:
59			return p.parseIfStmt()
60		case ast.TokenFor:
61			return p.parseForStmt()
62		case ast.TokenReturn:
63			return p.parseReturnStmt()
64		case ast.TokenStruct:
65			return p.parseStructDecl()
66		case ast.TokenLBrace:
67			return p.parseBlockStmt()
68		case ast.TokenSemicolon:
69			p.nextToken()
70			return nil, nil
71		default:
72			// Try to parse as expression statement
73			expr, err := p.parseExpression(0)
74			if err != nil {
75				return nil, err
76			}
77			return expr, nil
78		}
79	}
80	
81	func (p *Parser) parseLetDecl() (*ast.Node, error) {
82		letNode := &ast.Node{
83			Kind: ast.NodeLetDecl,
84			Line: p.curToken.Line,
85			Col:  p.curToken.Col,
86		}
87	
88		p.nextToken() // consume 'let'
89	
90		if p.curToken.Type != ast.TokenIdent {
91			return nil, fmt.Errorf("expected identifier after 'let'")
92		}
93	
94		nameNode := &ast.Node{
95			Kind:  ast.NodeIdent,
96			Value: p.curToken.Value,
97			Line:  p.curToken.Line,
98			Col:   p.curToken.Col,
99		}
100		letNode.Children = append(letNode.Children, nameNode)
101	
102		p.nextToken() // consume identifier
103	
104		// Check for type annotation: let x: int = ...
105		if p.curToken.Type == ast.TokenColon {
106			p.nextToken() // consume ':'
107			if p.curToken.Type != ast.TokenIdent {
108				return nil, fmt.Errorf("expected type name after ':'")
109			}
110			nameNode.TypeAnnotation = p.curToken.Value // "int", "bool", "Point", etc.
111			p.nextToken()                              // consume type name
112		}
113	
114		if p.curToken.Type != ast.TokenAssign {
115			return nil, fmt.Errorf("expected '=' after identifier")
116		}
117	
118		p.nextToken() // consume '='
119	
120		expr, err := p.parseExpression(0)
121		if err != nil {
122			return nil, err
123		}
124		letNode.Children = append(letNode.Children, expr)
125	
126		return letNode, nil
127	}
128	
129	func (p *Parser) parseFnDecl() (*ast.Node, error) {
130		fnNode := &ast.Node{
131			Kind: ast.NodeFnDecl,
132			Line: p.curToken.Line,
133			Col:  p.curToken.Col,
134		}
135	
136		p.nextToken() // consume 'fn'
137	
138		if p.curToken.Type != ast.TokenIdent {
139			return nil, fmt.Errorf("expected function name")
140		}
141	
142		fnNode.Value = p.curToken.Value
143		p.nextToken()
144	
145		if p.curToken.Type != ast.TokenLParen {
146			return nil, fmt.Errorf("expected '(' after function name")
147		}
148	
149		p.nextToken()
150	
151		// Parse parameters with type annotations
152		for p.curToken.Type != ast.TokenRParen {
153			if p.curToken.Type != ast.TokenIdent {
154				return nil, fmt.Errorf("expected parameter name")
155			}
156			param := &ast.Node{
157				Kind:  ast.NodeIdent,
158				Value: p.curToken.Value,
159			}
160			p.nextToken()
161	
162			// Parse parameter type annotation if present
163			if p.curToken.Type == ast.TokenColon {
164				p.nextToken()
165				if p.curToken.Type == ast.TokenIdent {
166					param.TypeAnnotation = p.curToken.Value // Store type annotation
167					p.nextToken()
168				}
169			}
170	
171			fnNode.Children = append(fnNode.Children, param)
172	
173			if p.curToken.Type == ast.TokenComma {
174				p.nextToken()
175			}
176		}
177	
178		p.nextToken() // consume ')'
179	
180		// Parse return type annotation if present: fn add(...): int
181		if p.curToken.Type == ast.TokenColon {
182			p.nextToken()
183			if p.curToken.Type == ast.TokenIdent {
184				fnNode.TypeAnnotation = p.curToken.Value // Store return type
185				p.nextToken()
186			}
187		}
188	
189		if p.curToken.Type != ast.TokenLBrace {
190			return nil, fmt.Errorf("expected '{' for function body")
191		}
192	
193		body, err := p.parseBlockStmt()
194		if err != nil {
195			return nil, err
196		}
197		fnNode.Children = append(fnNode.Children, body)
198	
199		return fnNode, nil
200	}
201	
202	func (p *Parser) parseIfStmt() (*ast.Node, error) {
203		ifNode := &ast.Node{
204			Kind: ast.NodeIfStmt,
205			Line: p.curToken.Line,
206			Col:  p.curToken.Col,
207		}
208	
209		p.nextToken() // consume 'if'
210	
211		cond, err := p.parseExpression(0)
212		if err != nil {
213			return nil, err
214		}
215		ifNode.Children = append(ifNode.Children, cond)
216	
217		if p.curToken.Type != ast.TokenLBrace {
218			return nil, fmt.Errorf("expected '{' after if condition")
219		}
220	
221		body, err := p.parseBlockStmt()
222		if err != nil {
223			return nil, err
224		}
225		ifNode.Children = append(ifNode.Children, body)
226	
227		// Check for else branch
228		if p.curToken.Type == ast.TokenElse {
229			p.nextToken() // consume 'else'
230	
231			if p.curToken.Type != ast.TokenLBrace {
232				return nil, fmt.Errorf("expected '{' after else")
233			}
234	
235			elseBody, err := p.parseBlockStmt()
236			if err != nil {
237				return nil, err
238			}
239			ifNode.Children = append(ifNode.Children, elseBody)
240		}
241	
242		return ifNode, nil
243	}
244	
245	func (p *Parser) parseForStmt() (*ast.Node, error) {
246		forNode := &ast.Node{
247			Kind: ast.NodeForStmt,
248			Line: p.curToken.Line,
249			Col:  p.curToken.Col,
250		}
251	
252		p.nextToken() // consume 'for'
253	
254		if p.curToken.Type != ast.TokenIdent {
255			return nil, fmt.Errorf("expected iterator variable")
256		}
257	
258		iter := &ast.Node{
259			Kind:  ast.NodeIdent,
260			Value: p.curToken.Value,
261		}
262		forNode.Children = append(forNode.Children, iter)
263		p.nextToken()
264	
265		if p.curToken.Type != ast.TokenIn {
266			return nil, fmt.Errorf("expected 'in' after iterator")
267		}
268	
269		p.nextToken()
270	
271		rng, err := p.parseExpression(0)
272		if err != nil {
273			return nil, err
274		}
275		forNode.Children = append(forNode.Children, rng)
276	
277		if p.curToken.Type != ast.TokenLBrace {
278			return nil, fmt.Errorf("expected '{' for loop body")
279		}
280	
281		body, err := p.parseBlockStmt()
282		if err != nil {
283			return nil, err
284		}
285		forNode.Children = append(forNode.Children, body)
286	
287		return forNode, nil
288	}
