341	func (p *Parser) parseExpression(prec int) (*ast.Node, error) {
342		left, err := p.parsePrimary()
343		if err != nil {
344			return nil, err
345		}
346	
347		for prec < p.peekPrecedence() {
348			p.nextToken()
349			left, err = p.parseInfix(left)
350			if err != nil {
351				return nil, err
352			}
353		}
354	
355		return left, nil
356	}
357	
358	func (p *Parser) parsePrimary() (*ast.Node, error) {
359		switch p.curToken.Type {
360		case ast.TokenInt:
361			node := &ast.Node{
362				Kind:  ast.NodeIntLit,
363				Value: p.curToken.Value,
364				Line:  p.curToken.Line,
365				Col:   p.curToken.Col,
366			}
367			return node, nil
368	
369		case ast.TokenTrue:
370			node := &ast.Node{
371				Kind:  ast.NodeBoolLit,
372				Value: "true",
373				Line:  p.curToken.Line,
374				Col:   p.curToken.Col,
375			}
376			return node, nil
377	
378		case ast.TokenFalse:
379			node := &ast.Node{
380				Kind:  ast.NodeBoolLit,
381				Value: "false",
382				Line:  p.curToken.Line,
383				Col:   p.curToken.Col,
384			}
385			return node, nil
386	
387		case ast.TokenString:
388			node := &ast.Node{
389				Kind:  ast.NodeStringLit,
390				Value: p.curToken.Value,
391				Line:  p.curToken.Line,
392				Col:   p.curToken.Col,
393			}
394			return node, nil
395	
396		case ast.TokenIdent:
397			name := p.curToken.Value
398			node := &ast.Node{
399				Kind:  ast.NodeIdent,
400				Value: name,
401				Line:  p.curToken.Line,
402				Col:   p.curToken.Col,
403			}
404			// Check if next token is '{' for struct initialization
405			if p.peekToken.Type == ast.TokenLBrace {
406				p.nextToken() // move to '{'
407				return p.parseStructLit(name)
408			}
409			return node, nil
410	
411		case ast.TokenLParen:
412			p.nextToken()
413			expr, err := p.parseExpression(0)
414			if err != nil {
415				return nil, err
416			}
417			if p.curToken.Type != ast.TokenRParen {
418				return nil, fmt.Errorf("expected ')'")
419			}
420			return expr, nil
421	
422		case ast.TokenLBracket:
423			return p.parseArrayLit()
424	
425		default:
426			return nil, fmt.Errorf("unexpected token: %v", p.curToken.Type)
427		}
428	}
429	
430	func (p *Parser) parseInfix(left *ast.Node) (*ast.Node, error) {
431		// Handle field access: obj.field
432		if p.curToken.Type == ast.TokenDot {
433			p.nextToken() // consume '.'
434			if p.curToken.Type != ast.TokenIdent {
435				return nil, fmt.Errorf("expected field name after '.'")
436			}
437			return &ast.Node{
438				Kind:     ast.NodeFieldAccess,
439				Value:    p.curToken.Value,
440				Line:     p.curToken.Line,
441				Col:      p.curToken.Col,
442				Children: []*ast.Node{left},
443			}, nil
444		}
445	
446		// Handle array indexing: arr[i]
447		if p.curToken.Type == ast.TokenLBracket {
448			return p.parseIndexExpr(left)
449		}
450	
451		node := &ast.Node{
452			Kind:     ast.NodeBinaryExpr,
453			Line:     p.curToken.Line,
454			Col:      p.curToken.Col,
455			Value:    p.curToken.Value,
456			Children: []*ast.Node{left},
457		}
458	
459		prec := p.curPrecedence()
460		p.nextToken()
461	
462		right, err := p.parseExpression(prec)
463		if err != nil {
464			return nil, err
465		}
466		node.Children = append(node.Children, right)
467	
468		// Handle function calls
469		if left.Kind == ast.NodeIdent && p.curToken.Type == ast.TokenLParen {
470			call := &ast.Node{
471				Kind:  ast.NodeCallExpr,
472				Value: left.Value,
473			}
474			p.nextToken() // consume '('
475			for p.curToken.Type != ast.TokenRParen {
476				arg, err := p.parseExpression(0)
477				if err != nil {
478					return nil, err
479				}
480				call.Children = append(call.Children, arg)
481				if p.curToken.Type == ast.TokenComma {
482					p.nextToken()
483				}
484			}
485			p.nextToken() // consume ')'
486			return call, nil
487		}
488	
489		return node, nil
490	}
491	
492	func (p *Parser) peekPrecedence() int {
493		return precedence(p.peekToken.Type)
494	}
495	
496	func (p *Parser) curPrecedence() int {
497		return precedence(p.curToken.Type)
498	}
499	
500	func precedence(tok ast.TokenType) int {
501		switch tok {
502		case ast.TokenEq, ast.TokenNe, ast.TokenLt, ast.TokenGt, ast.TokenLe, ast.TokenGe:
503			return 1
504		case ast.TokenPlus, ast.TokenMinus:
505			return 2
506		case ast.TokenStar, ast.TokenSlash:
507			return 3
508		case ast.TokenDotDot:
509			return 4
510		case ast.TokenDot, ast.TokenLBracket:
511			return 5
512		default:
513			return 0
514		}
515	}
516	
517	func (p *Parser) skipSemicolons() {
518		for p.curToken.Type == ast.TokenSemicolon {
519			p.nextToken()
520		}
521	}
522	
523	func (p *Parser) parseStructDecl() (*ast.Node, error) {
524		structNode := &ast.Node{
525			Kind: ast.NodeStructDecl,
526			Line: p.curToken.Line,
527			Col:  p.curToken.Col,
528		}
529	
530		p.nextToken() // consume 'struct'
531	
532		if p.curToken.Type != ast.TokenIdent {
533			return nil, fmt.Errorf("expected struct name")
534		}
535	
536		structNode.Value = p.curToken.Value
537		p.nextToken()
538	
539		if p.curToken.Type != ast.TokenLBrace {
540			return nil, fmt.Errorf("expected '{' after struct name")
541		}
542	
543		p.nextToken() // consume '{'
544	
545		// Parse fields
546		for p.curToken.Type != ast.TokenRBrace {
547			field, err := p.parseFieldDecl()
548			if err != nil {
549				return nil, err
550			}
551			structNode.Children = append(structNode.Children, field)
552	
553			if p.curToken.Type == ast.TokenSemicolon {
554				p.nextToken()
555			}
556		}
557	
558		p.nextToken() // consume '}'
559	
560		return structNode, nil
561	}
562	
563	func (p *Parser) parseFieldDecl() (*ast.Node, error) {
564		if p.curToken.Type != ast.TokenIdent {
565			return nil, fmt.Errorf("expected field name")
566		}
567	
568		fieldNode := &ast.Node{
569			Kind:  ast.NodeFieldDecl,
570			Value: p.curToken.Value,
571			Line:  p.curToken.Line,
572			Col:   p.curToken.Col,
573		}
574	
575		p.nextToken() // consume field name
576	
577		if p.curToken.Type != ast.TokenColon {
578			return nil, fmt.Errorf("expected ':' after field name")
579		}
580	
581		p.nextToken() // consume ':'
582	
583		if p.curToken.Type != ast.TokenIdent {
584			return nil, fmt.Errorf("expected field type")
585		}
586	
587		typeNode := &ast.Node{
588			Kind:  ast.NodeIdent,
589			Value: p.curToken.Value,
590			Line:  p.curToken.Line,
591			Col:   p.curToken.Col,
592		}
593		fieldNode.TypeAnnotation = p.curToken.Value // Store type annotation directly
594		fieldNode.Children = append(fieldNode.Children, typeNode)
595	
596		p.nextToken() // consume type
597	
598		return fieldNode, nil
599	}
