601	// parseStructLit parses struct initialization: Point{x: 1, y: 2}
602	func (p *Parser) parseStructLit(name string) (*ast.Node, error) {
603		structLit := &ast.Node{
604			Kind:  ast.NodeStructLit,
605			Value: name,
606			Line:  p.curToken.Line,
607			Col:   p.curToken.Col,
608		}
609	
610		p.nextToken() // consume '{'
611	
612		for p.curToken.Type != ast.TokenRBrace && p.curToken.Type != ast.TokenEOF {
613			if p.curToken.Type != ast.TokenIdent {
614				return nil, fmt.Errorf("expected field name in struct init")
615			}
616	
617			fieldName := p.curToken.Value
618			p.nextToken()
619	
620			if p.curToken.Type != ast.TokenColon {
621				return nil, fmt.Errorf("expected ':' after field name in struct init")
622			}
623	
624			p.nextToken()
625	
626			// Parse field value expression
627			fieldValue, err := p.parseExpression(0)
628			if err != nil {
629				return nil, err
630			}
631	
632			// Create field initialization node
633			fieldInit := &ast.Node{
634				Kind:  ast.NodeFieldDecl,
635				Value: fieldName,
636			}
637			fieldInit.Children = append(fieldInit.Children, fieldValue)
638			structLit.Children = append(structLit.Children, fieldInit)
639	
640			if p.curToken.Type == ast.TokenComma {
641				p.nextToken()
642			}
643		}
644	
645		if p.curToken.Type != ast.TokenRBrace {
646			return nil, fmt.Errorf("expected '}' to close struct init")
647		}
648	
649		p.nextToken() // consume '}'
650	
651		return structLit, nil
652	}
653	
654	// parseArrayLit parses array literals: [1, 2, 3]
655	func (p *Parser) parseArrayLit() (*ast.Node, error) {
656		node := &ast.Node{
657			Kind:  ast.NodeArrayLit,
658			Line:  p.curToken.Line,
659			Col:   p.curToken.Col,
660			Children: []*ast.Node{},
661		}
662	
663		p.nextToken() // skip '['
664	
665		for p.curToken.Type != ast.TokenRBracket && p.curToken.Type != ast.TokenEOF {
666			elem, err := p.parseExpression(0)
667			if err != nil {
668				return nil, err
669			}
670			node.Children = append(node.Children, elem)
671	
672			if p.curToken.Type == ast.TokenComma {
673				p.nextToken()
674			} else if p.curToken.Type != ast.TokenRBracket {
675				return nil, fmt.Errorf("expected ',' or ']' in array literal")
676			}
677		}
678	
679		if p.curToken.Type != ast.TokenRBracket {
680			return nil, fmt.Errorf("expected ']' to close array literal")
681		}
682	
683		p.nextToken() // skip ']'
684		return node, nil
685	}
686	
687	// parseIndexExpr parses array indexing: arr[i]
688	func (p *Parser) parseIndexExpr(obj *ast.Node) (*ast.Node, error) {
689		node := &ast.Node{
690			Kind:     ast.NodeIndexExpr,
691			Line:     obj.Line,
692			Col:      obj.Col,
693			Children: []*ast.Node{obj},
694		}
695	
696		p.nextToken() // skip '['
697	
698		idx, err := p.parseExpression(0)
699		if err != nil {
700			return nil, err
701		}
702		node.Children = append(node.Children, idx)
703	
704		if p.curToken.Type != ast.TokenRBracket {
705			return nil, fmt.Errorf("expected ']' after array index")
706		}
707	
708		p.nextToken() // skip ']'
709		return node, nil
