1	package typesys
2	
3	import (
4		"fmt"
5	
6		"github.com/user/freelang-evolving-compiler/internal/ast"
7		"github.com/user/freelang-evolving-compiler/internal/builtin"
8	)
9	
10	// TypeError represents a type checking error
11	type TypeError struct {
12		Message string
13		Line    int
14		Col     int
15	}
16	
17	// TypeChecker validates types in an AST
18	type TypeChecker struct {
19		env      *TypeEnv
20		errors   []TypeError
21		hardMode bool // if true, type errors are fatal
22	}
23	
24	// NewTypeChecker creates a new type checker in soft mode
25	func NewTypeChecker() *TypeChecker {
26		env := NewTypeEnv()
27		registerBuiltinsInEnv(env)
28		return &TypeChecker{
29			env:      env,
30			errors:   []TypeError{},
31			hardMode: false,
32		}
33	}
34	
35	// NewTypeCheckerHard creates a new type checker in hard mode
36	func NewTypeCheckerHard() *TypeChecker {
37		env := NewTypeEnv()
38		registerBuiltinsInEnv(env)
39		return &TypeChecker{
40			env:      env,
41			errors:   []TypeError{},
42			hardMode: true,
43		}
44	}
45	
46	// registerBuiltinsInEnv registers all built-in function signatures in the environment
47	func registerBuiltinsInEnv(env *TypeEnv) {
48		for _, def := range builtin.AllDefs() {
49			// Convert type names to TypeInfo
50			paramTypes := make([]TypeInfo, len(def.ParamTypeNames))
51			for i, typeName := range def.ParamTypeNames {
52				paramTypes[i] = TypeFromAnnotation(typeName)
53			}
54			returnType := TypeFromAnnotation(def.ReturnTypeName)
55	
56			env.RegisterFunc(def.Name, FuncDef{
57				Name:       def.Name,
58				ParamTypes: paramTypes,
59				ReturnType: returnType,
60			})
61		}
62	}
63	
64	// Check walks the AST and validates types, returning any errors found
65	func (tc *TypeChecker) Check(root *ast.Node) []TypeError {
66		if root != nil {
67			tc.checkNode(root)
68		}
69		return tc.errors
70	}
71	
72	// checkNode recursively checks a node and returns its inferred type
73	func (tc *TypeChecker) checkNode(n *ast.Node) TypeInfo {
74		if n == nil {
75			return UnknownType
76		}
77	
78		switch n.Kind {
79		case ast.NodeProgram:
80			// Check all top-level statements
81			for _, child := range n.Children {
82				tc.checkNode(child)
83			}
84			return UnitType
85	
86		case ast.NodeStructDecl:
87			return tc.checkStructDecl(n)
88	
89		case ast.NodeLetDecl:
90			return tc.checkLetDecl(n)
91	
92		case ast.NodeFnDecl:
93			return tc.checkFnDecl(n)
94	
95		case ast.NodeBlockStmt:
96			tc.env.EnterScope()
97			for _, child := range n.Children {
98				tc.checkNode(child)
99			}
100			tc.env.ExitScope()
101			return UnitType
102	
103		case ast.NodeIfStmt:
104			if len(n.Children) > 0 {
105				condType := tc.checkNode(n.Children[0])
106				if condType.Kind != TypeBool && condType.Kind != TypeUnknown {
107					tc.addError(fmt.Sprintf("if condition must be bool, got %v", condType), n.Line, n.Col)
108				}
109			}
110			if len(n.Children) > 1 {
111				tc.checkNode(n.Children[1])
112			}
113			// Check else branch if present
114			if len(n.Children) > 2 {
115				tc.checkNode(n.Children[2])
116			}
117			return UnitType
118	
119		case ast.NodeReturn:
120			if len(n.Children) > 0 {
121				return tc.checkNode(n.Children[0])
122			}
123			return UnitType
124	
125		case ast.NodeBinaryExpr:
126			return tc.checkBinaryExpr(n)
127	
128		case ast.NodeFieldAccess:
129			return tc.checkFieldAccess(n)
130	
131		case ast.NodeCallExpr:
132			return tc.checkCallExpr(n)
133	
134		case ast.NodeIdent:
135			if t, found := tc.env.Lookup(n.Value); found {
136				return t
137			}
138			tc.addError(fmt.Sprintf("unknown variable '%s'", n.Value), n.Line, n.Col)
139			return UnknownType
140	
141		case ast.NodeIntLit:
142			return IntType
143	
144		case ast.NodeBoolLit:
145			return BoolType
146	
147		case ast.NodeStringLit:
148			return StringType
149	
150		case ast.NodeStructLit:
151			return tc.checkStructLit(n)
152	
153		case ast.NodeForStmt:
154			// Register iterator variable as int (simplified)
155			if len(n.Children) > 0 && n.Children[0].Kind == ast.NodeIdent {
156				tc.env.Define(n.Children[0].Value, IntType)
157			}
158			if len(n.Children) > 2 {
159				tc.checkNode(n.Children[2]) // body
160			}
161			return UnitType
162	
163		default:
164			return UnknownType
165		}
166	}
167	
168	// checkStructDecl registers a struct definition
169	func (tc *TypeChecker) checkStructDecl(n *ast.Node) TypeInfo {
170		structName := n.Value
171		def := StructDef{
172			Name:   structName,
173			Fields: make(map[string]TypeInfo),
174		}
175	
176		// Extract field types from children
177		for _, child := range n.Children {
178			if child.Kind == ast.NodeFieldDecl {
179				fieldName := child.Value
180				// Field type is in TypeAnnotation or Children[0].Value
181				fieldType := UnknownType
182				if child.TypeAnnotation != "" {
183					fieldType = TypeFromAnnotation(child.TypeAnnotation)
184				} else if len(child.Children) > 0 {
185					// Type is in Children[0].Value
186					fieldType = TypeFromAnnotation(child.Children[0].Value)
187				}
188				def.Fields[fieldName] = fieldType
189			}
190		}
191	
192		tc.env.RegisterStruct(structName, def)
193		return UnitType
194	}
195	
196	// checkLetDecl validates variable declaration and registration
197	func (tc *TypeChecker) checkLetDecl(n *ast.Node) TypeInfo {
198		if len(n.Children) < 2 {
199			return UnknownType
200		}
201	
202		nameNode := n.Children[0]
203		valueNode := n.Children[1]
204	
205		// Determine the type of the variable
206		var varType TypeInfo
207	
208		// If there's a type annotation, use it
209		if nameNode.TypeAnnotation != "" {
210			varType = TypeFromAnnotation(nameNode.TypeAnnotation)
211			// Check value type matches declared type
212			inferredType := tc.inferType(valueNode)
213			if inferredType.Kind != TypeUnknown && !varType.Equals(inferredType) {
214				tc.addError(
215					fmt.Sprintf("type mismatch: expected %v, got %v", varType, inferredType),
216					n.Line, n.Col,
217				)
218			}
219		} else {
220			// No annotation: infer from the value expression
221			varType = tc.inferType(valueNode)
222		}
223	
224		// Register the variable
225		tc.env.Define(nameNode.Value, varType)
226		return UnitType
227	}
228	
229	// checkFnDecl validates function declaration and registers function signature
230	func (tc *TypeChecker) checkFnDecl(n *ast.Node) TypeInfo {
231		fnName := n.Value
232	
233		// Collect parameter types
234		paramTypes := []TypeInfo{}
235		tc.env.EnterScope()
236	
237		for _, child := range n.Children {
238			if child.Kind == ast.NodeIdent {
239				// This is a parameter
240				paramType := UnknownType
241				if child.TypeAnnotation != "" {
242					paramType = TypeFromAnnotation(child.TypeAnnotation)
243				}
244				paramTypes = append(paramTypes, paramType)
245				tc.env.Define(child.Value, paramType)
246			}
247		}
248	
249		// Get return type from fn node's TypeAnnotation
250		returnType := UnitType
251		if n.TypeAnnotation != "" {
252			returnType = TypeFromAnnotation(n.TypeAnnotation)
253		}
254	
255		// Check function body
256		for _, child := range n.Children {
257			if child.Kind == ast.NodeBlockStmt {
258				tc.checkNode(child)
259				break
260			}
261		}
262	
263		tc.env.ExitScope()
264	
265		// Register function signature
266		fnDef := FuncDef{
267			Name:       fnName,
268			ParamTypes: paramTypes,
269			ReturnType: returnType,
270		}
271		tc.env.RegisterFunc(fnName, fnDef)
272	
273		return UnitType
274	}
275	
276	// checkBinaryExpr validates binary expression type correctness
277	func (tc *TypeChecker) checkBinaryExpr(n *ast.Node) TypeInfo {
278		if len(n.Children) < 2 {
279			return UnknownType
280		}
281	
282		leftType := tc.checkNode(n.Children[0])
283		rightType := tc.checkNode(n.Children[1])
284	
285		// For now, both operands must be int for arithmetic
286		op := n.Value
287		if op == "+" || op == "-" || op == "*" || op == "/" {
288			if leftType.Kind != TypeInt && leftType.Kind != TypeUnknown {
289				tc.addError(
290					fmt.Sprintf("left operand of %s must be int, got %v", op, leftType),
291					n.Line, n.Col,
292				)
293			}
294			if rightType.Kind != TypeInt && rightType.Kind != TypeUnknown {
295				tc.addError(
296					fmt.Sprintf("right operand of %s must be int, got %v", op, rightType),
297					n.Line, n.Col,
298				)
299			}
300			return IntType
301		}
302	
303		// Comparison operators return bool
304		if op == "==" || op == "!=" || op == "<" || op == ">" || op == "<=" || op == ">=" {
305			if !leftType.Equals(rightType) && leftType.Kind != TypeUnknown && rightType.Kind != TypeUnknown {
306				tc.addError(
307					fmt.Sprintf("type mismatch in %s: %v vs %v", op, leftType, rightType),
308					n.Line, n.Col,
309				)
310			}
311			return BoolType
312		}
313	
314		return UnknownType
315	}
316	
317	// checkFieldAccess validates field access and returns field type
318	func (tc *TypeChecker) checkFieldAccess(n *ast.Node) TypeInfo {
319		if len(n.Children) == 0 {
320			return UnknownType
321		}
322	
323		// Get the object type
324		objType := tc.checkNode(n.Children[0])
325		fieldName := n.Value
326	
327		// Look up struct definition
328		if objType.Kind == TypeStruct {
329			if structDef, found := tc.env.LookupStruct(objType.StructName); found {
330				if fieldType, fieldExists := structDef.Fields[fieldName]; fieldExists {
331					return fieldType
332				}
333				tc.addError(
334					fmt.Sprintf("unknown field '%s' on struct '%s'", fieldName, objType.StructName),
335					n.Line, n.Col,
336				)
337				return UnknownType
338			}
339			tc.addError(fmt.Sprintf("unknown struct '%s'", objType.StructName), n.Line, n.Col)
340			return UnknownType
341		}
342	
343		// Object is not a struct
344		if objType.Kind != TypeUnknown {
345			tc.addError(
346				fmt.Sprintf("cannot access field '%s' on non-struct type %v", fieldName, objType),
347				n.Line, n.Col,
348			)
349		}
350		return UnknownType
351	}
352	
353	// checkCallExpr validates function call and returns return type
354	func (tc *TypeChecker) checkCallExpr(n *ast.Node) TypeInfo {
355		fnName := n.Value
356	
357		// Check for user-defined or built-in function
358		if fnDef, found := tc.env.LookupFunc(fnName); found {
359			// Validate argument count
360			if len(n.Children) != len(fnDef.ParamTypes) {
361				tc.addError(
362					fmt.Sprintf("function '%s' expects %d arguments, got %d", fnName, len(fnDef.ParamTypes), len(n.Children)),
363					n.Line, n.Col,
364				)
365			}
366			// Return the function's return type
367			return fnDef.ReturnType
368		}
369	
370		// Unknown function
371		tc.addError(fmt.Sprintf("unknown function '%s'", fnName), n.Line, n.Col)
372		return UnknownType
373	}
374	
375	// inferType infers the type of a node without modifying the environment
376	func (tc *TypeChecker) inferType(n *ast.Node) TypeInfo {
377		if n == nil {
378			return UnknownType
379		}
380	
381		switch n.Kind {
382		case ast.NodeIntLit:
383			return IntType
384		case ast.NodeBoolLit:
385			return BoolType
386		case ast.NodeStringLit:
387			return StringType
388		case ast.NodeStructLit:
389			// Infer struct type from the struct name
390			return StructType(n.Value)
391		case ast.NodeIdent:
392			// Look up variable type
393			if t, found := tc.env.Lookup(n.Value); found {
394				return t
395			}
396			return UnknownType
397		case ast.NodeBinaryExpr:
398			return tc.checkBinaryExpr(n)
399		case ast.NodeFieldAccess:
400			return tc.checkFieldAccess(n)
401		case ast.NodeCallExpr:
402			return tc.checkCallExpr(n)
403		default:
404			return UnknownType
405		}
406	}
407	
408	// checkStructLit validates struct initialization
409	func (tc *TypeChecker) checkStructLit(n *ast.Node) TypeInfo {
410		structName := n.Value
411	
412		// Look up struct definition
413		if structDef, found := tc.env.LookupStruct(structName); found {
414			// Validate field initializations
415			for _, child := range n.Children {
416				if child.Kind == ast.NodeFieldDecl {
417					fieldName := child.Value
418					if _, fieldExists := structDef.Fields[fieldName]; !fieldExists {
419						tc.addError(
420							fmt.Sprintf("unknown field '%s' in struct '%s'", fieldName, structName),
421							child.Line, child.Col,
422						)
423					}
424					// Check field value type if we have field type info
425					if len(child.Children) > 0 {
426						fieldValueType := tc.inferType(child.Children[0])
427						expectedType := structDef.Fields[fieldName]
428						if fieldValueType.Kind != TypeUnknown && expectedType.Kind != TypeUnknown && !fieldValueType.Equals(expectedType) {
429							tc.addError(
430								fmt.Sprintf("field '%s' type mismatch: expected %v, got %v", fieldName, expectedType, fieldValueType),
431								child.Line, child.Col,
432							)
433						}
434					}
435				}
436			}
437			return StructType(structName)
438		}
439	
440		// Struct not found
441		tc.addError(fmt.Sprintf("unknown struct '%s'", structName), n.Line, n.Col)
442		return UnknownType
443	}
444	
445	// addError records a type error
446	func (tc *TypeChecker) addError(msg string, line, col int) {
447		tc.errors = append(tc.errors, TypeError{
448			Message: msg,
449			Line:    line,
450			Col:     col,
451		})
452	}
